///////////////////////////////////////////////////////////////////////////////
// FILE:          WidefieldGpuD3D11.h
// PROJECT:       insiliscope
// SUBSYSTEM:     Simulation engine (no MMDevice dependency)
//-----------------------------------------------------------------------------
// DESCRIPTION:   The WideField GPU host of the adapter: WidefieldGpuHost (the
//                algorithm, shared with the Linux server's WidefieldGpuWebGpu)
//                on a Direct3D 11 backend that runs the kernels of
//                WidefieldGpu.wgsl as HLSL (generated by tools/gen_wf_gpu.mjs,
//                WidefieldGpuHlsl.inc).
//
//                Create() rejects software adapters (as GpuSimD3D11) and runs
//                the host's self-check, so a driver or compiler that gets the
//                kernels wrong leaves the CPU path in charge. Windows only;
//                elsewhere Create() returns nullptr.
//
// LICENSE:       BSD-3-Clause (see LICENSE at the repository root)

#pragma once

#include "WidefieldGpuHost.h"

#include <memory>
#include <string>

namespace sim {

class WidefieldGpuD3D11 : public WidefieldGpuHost
{
public:
   // nullptr (info = why) if there is no usable hardware device, a kernel
   // does not compile, or the self-check fails; info = the adapter otherwise.
   static std::unique_ptr<WidefieldGpuD3D11> Create(std::string& info);

private:
   explicit WidefieldGpuD3D11(std::unique_ptr<GpuBackend> backend) : WidefieldGpuHost(std::move(backend)) {}
};

} // namespace sim
